-- 2) MiningExample: "Task Mining — Enter Invoice" (1 row)
INSERT INTO "MiningExample" ("id", "slug", "title", "concept", "description", "difficulty", "sortOrder", "published", "package", "createdById", "createdAt", "updatedAt") VALUES ('cmsnxibpp0000po1kce9vucg0', 'task-mining-enter-invoice', 'Task Mining — Enter Invoice', 'Mine the UI steps inside one task to expose rework, app ping-pong and automation potential.', '**Task Mining** looks *inside* a single process task at the UI steps a person actually performs. This example is **Enter Invoice** — the clerk copies the Vendor and Amount from an Excel sheet into an Accounts-Payable web form, validates, and submits.  Import the log and you''ll see the **task routine map**: the happy path, plus a **rework loop** where a failed validation sends the clerk back to Excel to re-copy the Amount (classic **ping-pong** between two apps). The heavy copy/paste + app-switching makes this a strong **RPA automation candidate** — exactly what Task Mining is for.', 'advanced', 40, TRUE, '{"run":{"name":"Enter Invoice — task routine","stats":{"to":1772815100000,"from":1772442000000,"cases":100,"events":1150,"states":["Chrome: Paste Amount","Chrome: Paste Vendor","Chrome: Submit","Chrome: Validate","Excel: Copy Amount","Excel: Copy Vendor","Open Excel","Switch to Chrome","Switch to Excel"],"variants":2,"activities":["Chrome: Paste Amount","Chrome: Paste Vendor","Chrome: Submit","Chrome: Validate","Excel: Copy Amount","Excel: Copy Vendor","Open Excel","Switch to Chrome","Switch to Excel"]},"mapping":{"caseId":"taskCaseId","activity":"activity","resource":"actor","timestamp":"timestamp","entityType":"object"},"variants":[{"count":70,"events":["Open Excel","Excel: Copy Vendor","Switch to Chrome","Chrome: Paste Vendor","Switch to Excel","Excel: Copy Amount","Switch to Chrome","Chrome: Paste Amount","Chrome: Validate","Chrome: Submit"],"states":["Open Excel","Excel: Copy Vendor","Switch to Chrome","Chrome: Paste Vendor","Switch to Excel","Excel: Copy Amount","Switch to Chrome","Chrome: Paste Amount","Chrome: Validate","Chrome: Submit"]},{"count":30,"events":["Open Excel","Excel: Copy Vendor","Switch to Chrome","Chrome: Paste Vendor","Switch to Excel","Excel: Copy Amount","Switch to Chrome","Chrome: Paste Amount","Chrome: Validate","Switch to Excel","Excel: Copy Amount","Switch to Chrome","Chrome: Paste Amount","Chrome: Validate","Chrome: Submit"],"states":["Open Excel","Excel: Copy Vendor","Switch to Chrome","Chrome: Paste Vendor","Switch to Excel","Excel: Copy Amount","Switch to Chrome","Chrome: Paste Amount","Chrome: Validate","Switch to Excel","Excel: Copy Amount","Switch to Chrome","Chrome: Paste Amount","Chrome: Validate","Chrome: Submit"]}],"analytics":{"cases":[{"idx":0,"endMs":1772442047000,"caseId":"INV-1042","events":10,"cycleMs":47000,"startMs":1772442000000,"variantIdx":0},{"idx":1,"endMs":1772443524000,"caseId":"INV-1043","events":10,"cycleMs":47000,"startMs":1772443477000,"variantIdx":0},{"idx":2,"endMs":1772445001000,"caseId":"INV-1044","events":10,"cycleMs":47000,"startMs":1772444954000,"variantIdx":0},{"idx":3,"endMs":1772446478000,"caseId":"INV-1045","events":10,"cycleMs":47000,"startMs":1772446431000,"variantIdx":0},{"idx":4,"endMs":1772447835000,"caseId":"INV-1046","events":10,"cycleMs":47000,"startMs":1772447788000,"variantIdx":0},{"idx":5,"endMs":1772449312000,"caseId":"INV-1047","events":10,"cycleMs":47000,"startMs":1772449265000,"variantIdx":0},{"idx":6,"endMs":1772450789000,"caseId":"INV-1048","events":10,"cycleMs":47000,"startMs":1772450742000,"variantIdx":0},{"idx":7,"endMs":1772452176000,"caseId":"INV-1049","events":15,"cycleMs":77000,"startMs":1772452099000,"variantIdx":1},{"idx":8,"endMs":1772453653000,"caseId":"INV-1050","events":15,"cycleMs":77000,"startMs":1772453576000,"variantIdx":1},{"idx":9,"endMs":1772455130000,"caseId":"INV-1051","events":15,"cycleMs":77000,"startMs":1772455053000,"variantIdx":1},{"idx":10,"endMs":1772456457000,"caseId":"INV-1052","events":10,"cycleMs":47000,"startMs":1772456410000,"variantIdx":0},{"idx"